"""
The bundled DFL runtime lock (RF-501 slice E): ``resources/dfl_runtime.lock.json``.

The lock ships inside the (signed) app, so every artifact's sha256 is
anchored in the app's code signature and nothing is fetched to decide what
to trust. It is generated by the recaster-dfl release CI and committed by PR.

Shape (schema 1)::

    {"schema": 1, "runtime": "recaster-dfl", "tag": "rdfl-2026.10.0", "placeholder": false,
     "dfl": {"repo": ..., "commit": "<40 hex>", "upstream": ..., "bridge_protocol": 1, "bridge_version": "1.0.0"},
     "artifacts": {
         "source":  {"name", "urls": [...], "sha256", "size", "unpacked_size", "format"},
         "weights": {... same ...},
         "envs": {"<platform>": {... same ..., "env_id", "python", "pins": {...}, "conda_unpack": true,
                                 "min_driver"?, "min_os"?}}},
     "signature": null, "signing_key_id": null}

``placeholder: true`` marks a dev lock with nothing published yet (``source``
and ``weights`` may then be null and ``envs`` empty); the runtime manager
reports "no runtime published" instead of offering a download.
``signature``/``signing_key_id`` are reserved for RF-411 (a remotely fetched
lock); they must stay null until that lands.

Pure: no Qt.
"""

import re
from pathlib import Path
from typing import Dict, List, Literal, Optional
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

LOCK_SCHEMA = 1
LOCK_FILE_NAME = "dfl_runtime.lock.json"

# Platform keys of artifacts.envs (see runtime_manager.current_platform)
PLATFORMS = ("linux-x86_64-cuda12", "macos-arm64-metal", "windows-x86_64-cuda11")

# Hosts allowed to serve runtime artifacts (https only, redirects included).
# R2 plus GitHub Releases and its redirect targets (design §4.5).
RUNTIME_ALLOWED_HOSTS = frozenset({
    "runtimes.recaster.studio",
    "github.com",
    "objects.githubusercontent.com",
    "release-assets.githubusercontent.com",
})

ARCHIVE_FORMATS = ("tar.gz", "tar", "zip")

_SHA256_RE = re.compile(r"[0-9a-f]{64}")
_COMMIT_RE = re.compile(r"[0-9a-f]{40}")
_SAFE_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*")
_SAFE_FILE_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._+-]*")


def is_allowed_runtime_url(url) -> bool:
    """True if ``url`` is https on an allowlisted host (default port, no userinfo).

    Same rules as ``services.updater.is_allowed_update_url`` with the
    runtime hosts.
    """
    try:
        parts = urlsplit(url)
        port = parts.port
    except (ValueError, TypeError, AttributeError):
        return False
    if parts.scheme != "https":
        return False
    if (parts.hostname or "").lower() not in RUNTIME_ALLOWED_HOSTS:
        return False
    if parts.username or parts.password:
        return False
    return port in (None, 443)


def _safe_name(value: str, what: str) -> str:
    if not _SAFE_NAME_RE.fullmatch(value) or value in (".", ".."):
        raise ValueError(f"{what} must be a plain name ([A-Za-z0-9._-]), got {value!r}")
    return value


class Artifact(BaseModel):
    """One downloadable archive.

    ``unpacked_size`` is the sum of the apparent sizes (``st_size``) of the
    archive's regular files, counting every path, hard-linked paths included.
    That's the conservative value: extraction counts a hard link only when it
    has to copy it (no hard links on the volume), so the real bytes written
    are never more than this. The disk preflight and the extraction cap
    (``unpacked_size x 1.1`` + slack) both use it. The E2 artifact builder
    must compute it this way, not from ``du`` (block usage, links counted once).
    """
    model_config = ConfigDict(extra="forbid", frozen=True)

    name: str
    urls: List[str] = Field(min_length=1)
    sha256: str
    size: int = Field(gt=0)            # bytes on the wire
    unpacked_size: int = Field(ge=0)   # sum of regular-file sizes, every path counted (see above)
    format: Literal["tar.gz", "tar", "zip"]

    @field_validator("name")
    @classmethod
    def _check_name(cls, value: str) -> str:
        if not _SAFE_FILE_RE.fullmatch(value) or ".." in value:
            raise ValueError(f"artifact name must be a bare file name, got {value!r}")
        return value

    @field_validator("urls")
    @classmethod
    def _check_urls(cls, value: List[str]) -> List[str]:
        for url in value:
            if not is_allowed_runtime_url(url):
                raise ValueError(f"artifact URL is not https on a trusted runtime host: {url}")
        return value

    @field_validator("sha256")
    @classmethod
    def _check_sha(cls, value: str) -> str:
        if not _SHA256_RE.fullmatch(value):
            raise ValueError("sha256 must be 64 lowercase hex characters")
        return value


class EnvArtifact(Artifact):
    """A conda-pack'ed TensorFlow environment for one platform."""
    env_id: str                        # directory name under runtimes/envs/, keyed by the conda-lock hash
    python: str                        # interpreter version inside the env, informational
    pins: Dict[str, str] = Field(default_factory=dict)
    conda_unpack: bool = True          # run the env's bin/conda-unpack once after extraction
    min_driver: Optional[str] = None
    min_os: Optional[str] = None

    @field_validator("env_id")
    @classmethod
    def _check_env_id(cls, value: str) -> str:
        return _safe_name(value, "env_id")


class DFLInfo(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    repo: str
    commit: str
    upstream: Optional[str] = None
    bridge_protocol: int = Field(ge=1)
    bridge_version: str

    @field_validator("commit")
    @classmethod
    def _check_commit(cls, value: str) -> str:
        if not _COMMIT_RE.fullmatch(value):
            raise ValueError("dfl.commit must be a 40-character lowercase hex commit")
        return value


class Artifacts(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    source: Optional[Artifact] = None
    weights: Optional[Artifact] = None
    envs: Dict[str, EnvArtifact] = Field(default_factory=dict)

    @field_validator("envs")
    @classmethod
    def _check_platforms(cls, value: Dict[str, EnvArtifact]) -> Dict[str, EnvArtifact]:
        for platform in value:
            if platform not in PLATFORMS:
                raise ValueError(f"unknown platform {platform!r} (expected one of {', '.join(PLATFORMS)})")
        return value


class RuntimeLock(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, populate_by_name=True)

    schema_version: int = Field(alias="schema")
    runtime: Literal["recaster-dfl"]
    tag: str
    placeholder: bool = False
    comment: Optional[str] = None
    dfl: DFLInfo
    artifacts: Artifacts
    signature: Optional[str] = None       # reserved: RF-411
    signing_key_id: Optional[str] = None  # reserved: RF-411

    @field_validator("schema_version")
    @classmethod
    def _check_schema(cls, value: int) -> int:
        if value != LOCK_SCHEMA:
            raise ValueError(f"unsupported lock schema {value} (this app reads schema {LOCK_SCHEMA})")
        return value

    @field_validator("tag")
    @classmethod
    def _check_tag(cls, value: str) -> str:
        return _safe_name(value, "tag")

    @model_validator(mode="after")
    def _check_published(self) -> "RuntimeLock":
        if not self.placeholder and (self.artifacts.source is None or self.artifacts.weights is None):
            raise ValueError("a published lock needs both the source and weights artifacts")
        if self.signature is not None or self.signing_key_id is not None:
            raise ValueError("lock signatures are reserved for RF-411 and not supported yet")
        return self

    def env_for(self, platform: Optional[str]) -> Optional[EnvArtifact]:
        if platform is None:
            return None
        return self.artifacts.envs.get(platform)

    def is_published_for(self, platform: Optional[str]) -> bool:
        return (not self.placeholder and self.artifacts.source is not None
                and self.artifacts.weights is not None and self.env_for(platform) is not None)


def bundled_lock_path() -> Path:
    return Path(__file__).resolve().parent.parent / "resources" / LOCK_FILE_NAME


def load_lock(path: Path) -> RuntimeLock:
    """Read and validate a lock file. Raises ``OSError`` / ``pydantic.ValidationError``."""
    return RuntimeLock.model_validate_json(Path(path).read_bytes())


def load_bundled_lock() -> RuntimeLock:
    return load_lock(bundled_lock_path())
